// Checkout conversion fix: ensure paidEvents increments on successful payment
// This module intercepts the checkout completion flow and forces conversion tracking

const revenueModule = require('./revenue-module');

module.exports = function(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function(body) {
    if (res.statusCode === 200 && body && body.success) {
      // Trigger revenue event
      revenueModule.recordEvent({
        type: 'checkout_complete',
        amount: body.amount || 0,
        currency: 'USD',
        timestamp: Date.now()
      });
    }
    return originalJson(body);
  };
  next();
};
